    const wf = fr(i * 7 + 5);
    S.warm[i] = wf < 0.13 ? 1 : 0;
    S.hj[i] = fr(i * 7 + 6);
    S.br[i] = fr(i * 7 + 9) < 0.06 ? 1 : (0.4 + fr(i * 7 + 11) * 0.45); // few heroes
