  // 3 faint nebula blobs, seed-placed
  const bx = [fr(1), fr(3), fr(5)], by = [fr(2), fr(4), fr(6)], bh = [fr(7), fr(8), fr(9)];
  // style palette (background tint) in rgb 0..1
  function bgcol(h) {
